import type { MouseEvent, ReactNode } from 'react';
import { BackButton } from './BackButton';
import { Button } from './Button';
import { Hint } from './Hint';
import { Tag } from './Tag';
import './LegalDoc.css';

export interface DocSection {
  /** Anchor id (also the `href="#id"` of its contents entry). Must be unique in the document. */
  id: string;
  title: string;
  body: ReactNode;
}

export interface LegalDocProps {
  title: string;
  /** "Version 2026-10-21", worded by the caller from the version table. */
  versionLabel: string;
  /** "Last updated 21 October 2026", generated by the caller from the version. */
  updatedLabel: string;
  sections: readonly DocSection[];
  /** The brand mark in the header (a link home). */
  brand: ReactNode;
  brandHref?: string;
  /** Back / Close control at the start of the header. Absent = none. */
  backLabel?: string;
  onBack?: () => void;
  brandLabel: string;
  /** End of the header: the app's language selector. */
  headerEnd?: ReactNode;
  /** Name of the contents landmark ("Contents"). */
  contentsLabel: string;
  saveLabel: string;
  printLabel: string;
  /** Honest note under the buttons: saving as PDF is the print dialog. */
  saveHint: string;
  /** Both buttons call this (the page passes `window.print`). */
  onPrint: () => void;
  /** Quiet note under the text (for example "shown in English"). */
  note?: string;
  /** The footer row (`LegalLinks`). */
  footer?: ReactNode;
}

/** A table inside a section (columns scroll sideways inside their box on a phone instead of widening the page). */
export function DocTable({
  head,
  rows,
}: {
  head: readonly string[];
  rows: readonly (readonly ReactNode[])[];
}) {
  return (
    <div className="uild-table">
      <table>
        <thead>
          <tr>
            {head.map((h) => (
              <th key={h} scope="col">
                {h}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, r) => (
            <tr key={r}>
              {row.map((cell, c) => (
                <td key={c}>{cell}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/**
 * The reader for the public legal documents (Privacy Policy, Terms of Use): brand header, version and date,
 * contents with anchors, "Save as PDF" and "Print" (the print dialog; a print stylesheet drops the chrome), numbered
 * sections, footer. Presentational: texts, links, language selector and the print action come through props.
 */
export function LegalDoc({
  title,
  versionLabel,
  updatedLabel,
  sections,
  brand,
  brandHref = '#/',
  backLabel,
  onBack,
  brandLabel,
  headerEnd,
  contentsLabel,
  saveLabel,
  printLabel,
  saveHint,
  onPrint,
  note,
  footer,
}: LegalDocProps) {
  // The app routes on the URL hash, so a plain `#section` jump would be read as a route: scroll instead.
  const jump = (e: MouseEvent<HTMLAnchorElement>, id: string) => {
    const el = document.getElementById(id);
    if (!el) return;
    e.preventDefault();
    el.scrollIntoView?.({ behavior: 'smooth', block: 'start' });
  };
  return (
    <div className="uild">
      <div className="uild-page">
        <header className="uild-head uild-noprint">
          {onBack && backLabel ? (
            <BackButton label={backLabel} text={backLabel} onClick={onBack} />
          ) : null}
          <a className="uild-brand" href={brandHref} aria-label={brandLabel}>
            {brand}
          </a>
          {headerEnd}
        </header>
        <div className="uild-grid">
          <aside className="uild-toc uild-noprint">
            <div className="uild-meta">
              <Tag tone="neutral">{versionLabel}</Tag>
              <span className="ut-xs ut-faint">{updatedLabel}</span>
            </div>
            <nav aria-label={contentsLabel} className="uild-nav">
              {sections.map((s, i) => (
                <a
                  key={s.id}
                  href={`#${s.id}`}
                  className="uild-nav-a ut-sm"
                  onClick={(e) => jump(e, s.id)}
                >
                  {i + 1}. {s.title}
                </a>
              ))}
            </nav>
            <div className="uild-acts">
              <Button variant="secondary" size="sm" icon="download-simple" onClick={onPrint}>
                {saveLabel}
              </Button>
              <Button variant="ghost" size="sm" icon="printer" onClick={onPrint}>
                {printLabel}
              </Button>
            </div>
            <Hint>{saveHint}</Hint>
          </aside>
          <article className="uild-body">
            <h1 className="ut-3xl ut-w7">{title}</h1>
            <p className="uild-print-meta ut-sm">
              {versionLabel} · {updatedLabel}
            </p>
            {sections.map((s, i) => (
              <section key={s.id} id={s.id} className="uild-sec" aria-labelledby={`${s.id}-h`}>
                <h2 id={`${s.id}-h`} className="ut-lg ut-w7">
                  {i + 1}. {s.title}
                </h2>
                <div className="uild-text ut-base">{s.body}</div>
              </section>
            ))}
            {note ? <Hint className="uild-noprint">{note}</Hint> : null}
          </article>
        </div>
        {footer ? <footer className="uild-foot uild-noprint">{footer}</footer> : null}
      </div>
    </div>
  );
}
